using System;
using System.Reflection;
namespace Downfield {
public static class BowlingTests {
 public static int Run(){int checks=0,failures=0;Action<bool,string> test=(ok,label)=>{checks++;if(!ok){failures++;Console.WriteLine("FAIL Bowling: "+label);}};BowlingCard card=new BowlingCard();for(int n=0;n<12;n++)card.Roll(10);test(card.Complete&&card.Score==300,"twelve strikes are a perfect 300");card=new BowlingCard();for(int n=0;n<21;n++)card.Roll(5);test(card.Complete&&card.Score==150,"all five-pin spares score 150");card=new BowlingCard();for(int n=0;n<10;n++){card.Roll(9);card.Roll(0);}test(card.Complete&&card.Score==90,"nine and miss every frame scores 90");card=new BowlingCard();for(int n=0;n<20;n++)card.Roll(0);test(card.Complete&&card.Score==0,"all gutters end at zero");card=new BowlingCard();card.Roll(10);test(!card.Cumulative()[0].HasValue,"strike waits for two following plays");card.Roll(3);card.Roll(6);test(card.Cumulative()[0]==19&&card.Cumulative()[1]==28,"strike adds actual next two plays");card=new BowlingCard();card.Roll(7);card.Roll(3);card.Roll(4);test(card.Cumulative()[0]==14&&!card.Cumulative()[1].HasValue,"spare adds only next play");for(int variant=0;variant<4;variant++){card=new BowlingCard();for(int n=0;n<18;n++)card.Roll(0);if(variant==0){card.Roll(10);card.Roll(7);test(card.PinsLeft==3,"tenth strike then seven leaves three for fill");card.Roll(3);test(card.Complete&&card.Score==20,"tenth strike plus spare fill scores twenty");}if(variant==1){card.Roll(10);card.Roll(10);test(card.PinsLeft==10,"tenth double resets fill to ten yards");card.Roll(10);test(card.Complete&&card.Score==30,"tenth three strikes score thirty");}if(variant==2){card.Roll(6);card.Roll(4);test(!card.Complete&&card.PinsLeft==10,"tenth spare earns one fresh ten-yard play");card.Roll(9);test(card.Complete&&card.Score==19,"tenth spare plus nine scores nineteen");}if(variant==3){card.Roll(4);card.Roll(5);test(card.Complete&&card.Score==9,"open tenth has no bonus attempts");}}
  FootballBowling match=new FootballBowling();match.Record(4);test(match.Turn==0&&match.Current.PinsLeft==6,"second attempt belongs to same team and continues from gain");match.Record(6);test(match.Turn==1&&match.LastResult=="SPARE!","spare passes turn to opposing team");match.Record(10);test(match.Turn==0&&match.Current.Frame==1,"strike passes turn back for next frame");for(int n=0;n<100&&!match.Complete;n++)match.Record(0);test(match.Complete,"alternating teams complete all ten frames");
  Simulation s=new Simulation(51);s.StartBowlingRoll(10);test(s.Spot==90&&s.FirstDown==100&&s.Bowling&&!s.Practice,"bowling starts against real defenders at opponent ten");s.Punt();s.FieldGoal();test(s.State==Phase.PreSnap&&!s.RequestOnsideTry()&&!s.SimDrive(),"bowling cannot kick onside or simulate normal drives");s.SimRest();test(s.State==Phase.PreSnap,"normal game sim cannot bypass bowling scoring");s.Snap();typeof(Simulation).GetMethod("EndPlay",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,new object[]{94.8f,"TACKLED",false});test(s.BowlingRollFinished&&s.BowlingPins==4&&s.State==Phase.Dead,"open roll scores whole yards gained");s.StartBowlingRoll(6);test(s.Spot==94,"spare attempt uses remaining six yards");s.Snap();s.Controlled.Z=101;s.Update(.02f,0,0);test(s.BowlingRollFinished&&s.BowlingPins==6&&s.HomeScore==0&&s.State!=Phase.Conversion,"touchdown takes remaining pins without PAT");s.StartBowlingRoll(10);s.Snap();typeof(Simulation).GetMethod("BeginOpponent",BindingFlags.Instance|BindingFlags.NonPublic,null,new Type[]{typeof(string)},null).Invoke(s,new object[]{"INTERCEPTED"});test(s.BowlingPins==0&&s.BowlingRollFinished&&s.State==Phase.Dead,"turnover is a zero-pin attempt without normal opponent drive");Console.WriteLine("Bowling: "+checks+" checks, "+failures+" failures");return failures;}
}
}
